<template>
  <section class="stock-investors" :class="{compact}">
    <div class="stock-section-heading"><div><h2>{{ people.length }} investors, individual decisions</h2><p>Recorded private views and peer responses · market fills are separate.</p></div><span class="stock-subtle">{{ people.filter(p=>p.decision).length }} current decisions</span></div>
    <p v-if="!people.length" class="stock-empty">Investor profiles appear after the company and strategy evidence has been checked.</p>
    <template v-else>
      <details class="investor-filter-details"><summary>Find by strategy or name</summary><div class="investor-controls"><div><label for="stock-investor-strategy">Strategy</label><select id="stock-investor-strategy" v-model="family"><option value="">All strategies</option><option v-for="group in groups" :key="group.id" :value="group.id">{{ group.name }}</option></select></div><div><label for="stock-investor-search">Find an investor</label><input id="stock-investor-search" v-model="search" type="search" placeholder="Name or strategy"></div></div></details>
      <div class="investor-workspace">
        <div class="investor-network"><StockInvestorConversation :selected-id="selectedId" :run-id="runId" :status="status" :people="people" :rounds="rounds" @select="id=>{if(people.some(person=>person.id===id))selectedId=id}" @discussion="openInvestorDiscussion"/></div>
        <details v-if="selected" ref="inspector" class="investor-inspector portfolio-details" aria-label="Selected investor portfolio and records"><summary>Investor details · supplied peers, risk & portfolio · {{ selected.name }}</summary>
          <div class="inspector-heading"><h3>{{ selected.name }} <span>· {{ selected.strategy_name }}</span></h3><small>{{ selected.decision?'Saved decision':'Waiting for a decision' }}</small></div>
          <nav class="investor-detail-tabs" aria-label="Investor detail"><button v-for="item in [['view','Current view'],['debate','Discussion'],['profile','Portfolio & memory']]" :key="item[0]" :aria-pressed="detailTab===item[0]" @click="detailTab=item[0]">{{ item[1] }}</button></nav>
          <template v-if="detailTab==='view'"><template v-if="selected.decision"><h4>Current view</h4><p><StockEvidenceText :text="selected.decision.rationale" :sources="sources"/></p><h4>Strongest risk</h4><p><StockEvidenceText :text="selected.decision.strongest_risk" :sources="sources"/></p><dl class="portfolio-values"><div><dt>Target allocation</dt><dd>{{ allocation(selected.decision.target_allocation) }}</dd></div><div><dt>Reservation return assumption</dt><dd>{{ percent(selected.decision.reservation_return) }}</dd></div></dl></template><p v-else class="stock-subtle">This investor has not returned a current model decision.</p></template>
          <template v-else-if="detailTab==='debate'"><article v-if="exchange.privateView" class="investor-message"><h4>{{ selected.name }} · Private view</h4><p><StockEvidenceText :text="exchange.privateView.message || exchange.privateView.rationale" :sources="sources"/></p></article><details v-if="exchange.peers.length" class="investor-peer-views" open><summary>{{ exchange.peers.length }} peer views supplied for discussion</summary><article v-for="peer in exchange.peers" :key="peer.id" class="investor-message"><button @click="selectedId=peer.id">{{ peer.name }} →</button><p><StockEvidenceText :text="peer.view.message || peer.view.rationale" :sources="sources"/></p></article></details><article v-if="exchange.response" class="investor-message investor-response"><h4>{{ selected.name }} · After discussion</h4><p><StockEvidenceText :text="exchange.response.message || exchange.response.rationale" :sources="sources"/></p><details><summary>Reasoning and strongest risk</summary><p>{{ exchange.response.rationale }}</p><p>{{ exchange.response.strongest_risk }}</p></details></article><p v-if="!exchange.privateView&&!exchange.response" class="stock-subtle">The per-round messages are unavailable in this saved report. The current decision and retained memory remain inspectable.</p><dl v-if="exchange.privateView&&exchange.response" class="portfolio-values"><div><dt>Allocation before discussion</dt><dd>{{ allocation(exchange.privateView.target_allocation) }}</dd></div><div><dt>Allocation after discussion</dt><dd>{{ allocation(exchange.response.target_allocation) }}</dd></div></dl></template>
          <template v-else><dl class="portfolio-values"><div><dt>Virtual cash</dt><dd>{{ money(selected.cash,currency) }}</dd></div><div><dt>Shares held</dt><dd>{{ number(selected.shares) }}</dd></div><div><dt>Marked equity</dt><dd>{{ money(selected.equity,currency) }}</dd></div><div><dt>Position limit</dt><dd>{{ allocation(selected.position_limit) }}</dd></div></dl><details v-if="selected.memory?.length"><summary>Decision memory · {{ selected.memory.length }} saved views</summary><article v-for="(item,i) in selected.memory.toReversed()" :key="i"><h4>{{ item.round===0?'Private view':'After discussion' }}</h4><p><StockEvidenceText :text="item.rationale" :sources="sources"/></p><blockquote>{{ item.message }}</blockquote></article></details></template>
          <div class="connected-investors"><h4>Connected investors</h4><div class="peer-list"><button v-for="id in selected.connections" :key="id" @click="selectedId=id">{{ people.find(p=>p.id===id)?.name||id }}</button></div></div>
        </details>
      </div>
      <details class="investor-table-details"><summary>All investor portfolios · {{ filtered.length }} matches</summary><div class="stock-table-wrap"><table class="stock-table"><thead><tr><th>Investor</th><th>Strategy</th><th>Cash</th><th>Shares</th><th>Target allocation</th></tr></thead><tbody><tr v-for="person in filtered" :key="person.id" :class="{chosen:selectedId===person.id}"><td><button class="stock-text-button" @click="selectedId=person.id">{{ person.name }}</button></td><td>{{ person.strategy_name }}</td><td>{{ money(person.cash,currency) }}</td><td>{{ number(person.shares) }}</td><td>{{ person.decision?allocation(person.decision.target_allocation):'Pending' }}</td></tr></tbody></table><p v-if="!filtered.length" class="stock-empty">No investors match these filters.</p></div></details>
    </template>
  </section>
</template>
<script setup>
import StockInvestorConversation from './StockInvestorConversation.vue'
import {computed,ref,watch,nextTick} from 'vue'
import {money,number,percent} from '../api/stocklab'
import StockEvidenceText from './StockEvidenceText.vue'
import {spreadNodes,investorExchange} from '../utils/presentationGraphs.mjs'
const props=defineProps({runId:{type:String,default:'stock-investors'},status:{type:String,default:'complete'},people:{type:Array,default:()=>[]},rounds:{type:Object,default:()=>({})},sources:{type:Array,default:()=>[]},currency:{type:String,default:'USD'},compact:Boolean})
const inspector=ref(null)
function openInvestorDiscussion(){detailTab.value='debate';nextTick(()=>{if(inspector.value)inspector.value.open=true;inspector.value?.scrollIntoView({block:'start'})})}
const selectedId=ref(''),family=ref(''),search=ref(''),detailTab=ref('debate')
const allocation=value=>Number.isFinite(value)?`${Math.round(value*100)}%`:'—'
const colors=['#568d77','#847a9b','#678cac','#a38a5a','#b4757c','#64959b','#899768','#927d66']
const groups=computed(()=>[...new Set(props.people.map(p=>p.strategy))].map((id,i)=>({id,name:props.people.find(p=>p.strategy===id)?.strategy_name,color:colors[i%colors.length]})))
const points=computed(()=>spreadNodes(props.people).map(p=>({...p,color:groups.value.find(g=>g.id===p.strategy)?.color||'#8291a2'})))
const edges=computed(()=>points.value.flatMap(a=>(a.connections||[]).map(id=>({id:`${a.id}-${id}`,a,b:points.value.find(p=>p.id===id)})).filter(e=>e.b)))
const filtered=computed(()=>props.people.filter(p=>(!family.value||p.strategy===family.value)&&`${p.name} ${p.strategy}`.toLowerCase().includes(search.value.toLowerCase())))
const selected=computed(()=>props.people.find(p=>p.id===selectedId.value))
const exchange=computed(()=>investorExchange(selected.value,props.rounds,props.people))
watch(()=>props.people,people=>{if(people.length&&!people.some(p=>p.id===selectedId.value))selectedId.value=people[0].id},{immediate:true})
watch(filtered,matches=>{if(!matches.some(p=>p.id===selectedId.value))selectedId.value=matches[0]?.id||''})
</script>
<style scoped>
