}.investor-detail-tabs button[aria-pressed=true]{color:#ad471b;border-bottom-color:#ef5517}.investor-inspector h4{font-size:11px;font-weight:500;color:#697589;margin:16px 0 8px}.investor-inspector p{font-size:13px;line-height:1.8;color:#52657a;margin:0}.portfolio-values{font-size:12px;margin:16px 0}.portfolio-values>div{display:flex;justify-content:space-between;gap:15px;border-bottom:1px solid #edf0f4;padding:8px 0}.portfolio-values dt{color:#697589}.portfolio-values dd{margin:0;font-variant-numeric:tabular-nums}.investor-message{padding:13px 0;border-bottom:1px solid #edf0f4}.investor-message h4{margin:0 0 8px}.investor-message>button{border:0;background:none;color:#a34b22;font-size:11px;padding:0 0 8px;cursor:pointer}.investor-peer-views{margin-top:15px}.investor-inspector summary{font-size:11px;color:#697589;cursor:pointer}.investor-response{padding-left:12px;border-left:2px solid #e8ddd5}.investor-message details{margin:12px 0}.investor-message details p{margin-top:10px}.investor-inspector details article{padding:15px 0;border-bottom:1px solid #edf0f4}.investor-inspector blockquote{margin:12px 0;padding-left:12px;border-left:2px solid #dfe7ee;font-size:12px;color:#697589}.connected-investors{border-top:1px solid #edf0f4;margin-top:14px}.peer-list{display:flex;gap:7px;flex-wrap:wrap}.peer-list button{font-size:11px;border:1px solid #e9edf2;background:white;padding:6px 9px;border-radius:6px;color:#65788b;cursor:pointer}.investor-table-details{margin-top:22px;font-size:12px;color:#697589}.investor-table-details>summary{cursor:pointer}.stock-table-wrap{overflow:auto;margin-top:15px}.stock-section-heading h2{font-size:19px}.stock-section-heading p{font-size:11px;line-height:1.7}.compact .investor-controls{margin-bottom:15px}@media(max-width:600px){.investor-controls{flex-wrap:wrap}.investor-controls>div{flex-basis:100%}.investor-network svg{height:240px;min-width:0}.investor-inspector{padding:15px 13px}.network-caption,.investor-picker{padding-left:13px;padding-right:13px}.inspector-heading{align-items:start;flex-wrap:wrap}.investor-detail-tabs button{font-size:10px;padding:9px 7px}}

.portfolio-details>summary{font-size:12px;font-weight:500;color:#506780;cursor:pointer}.portfolio-details[open]>summary{margin-bottom:14px}.investor-workspace{background:white;border:0;border-radius:0}.investor-inspector{border:1px solid #e2e9f0;border-radius:7px;margin-top:14px}
.stock-section-heading{margin:0 0 8px}.stock-section-heading h2{font-size:17px}.stock-section-heading p{margin:3px 0;font-size:10px}.stock-section-heading>.stock-subtle{font-size:10px}.investor-filter-details{font-size:11px;color:#718399;margin:8px 0 12px}.investor-filter-details>summary{cursor:pointer}.investor-filter-details .investor-controls{margin:10px 0}.investor-network :deep(.playback-toolbar){margin-bottom:8px}
</style>
